/** Failure raised while compiling a pattern. */
export class GlobError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [index] 0-based index into the pattern where the fault starts
   */
  constructor(message, index) {
    super(message);
    this.name = 'GlobError';
    this.index = index;
  }
}

/**
 * Compile a glob pattern into a matcher.
 *
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {(path: string) => boolean} matcher for whole paths
 */
export function compile(pattern, options = {}) {
  if (typeof pattern !== 'string') {
    throw new Error('pattern must be a string');
  }
  if (pattern === '') {
    throw new Error('pattern must not be empty');
  }

  const { dot = false, nocase = false } = options;
  const matcher = compileToRegex(pattern, { dot, nocase });
  return (path) => matcher.test(path);
}

/**
 * Test one path against one pattern.
 *
 * @param {string} path path to test
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {boolean} whether the whole path matches
 */
export function isMatch(path, pattern, options = {}) {
  if (typeof path !== 'string') {
    throw new Error('path must be a string');
  }
  return compile(pattern, options)(path);
}

/**
 * Keep the paths that match a pattern, in their original order.
 *
 * @param {string[]} paths paths to filter
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {string[]} the matching paths
 */
export function filter(paths, pattern, options = {}) {
  if (!Array.isArray(paths)) {
    throw new Error('paths must be an array');
  }
  const matcher = compile(pattern, options);
  return paths.filter(matcher);
}

/**
 * Compile glob pattern to RegExp
 * @param {string} pattern 
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {RegExp}
 */
function compileToRegex(pattern, options) {
  const { dot, nocase } = options;

  // Split pattern into segments
  const segments = pattern.split('/');
  const processedSegments = [];

  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i];

    if (segment === '**') {
      // Handle globstar
      if (processedSegments.length === 0 || processedSegments[processedSegments.length - 1] !== '**') {
        processedSegments.push('**');
      }
      // Skip adjacent ** segments
    } else if (segment === '') {
      // Handle leading/trailing slash or double slash
      if (processedSegments.length > 0 && processedSegments[processedSegments.length - 1] !== '') {
        processedSegments.push('');
      }
    } else {
      // Handle normal segment
      processedSegments.push(translateSegment(segment, { dot, nocase }));
    }
  }

  // Handle trailing slash
  if (pattern.endsWith('/') && processedSegments.length > 0 && processedSegments[processedSegments.length - 1] !== '') {
    processedSegments.push('');
  }

  // Build regex pattern
  let regexPattern = '^';

  for (let i = 0; i < processedSegments.length; i++) {
    const segment = processedSegments[i];

    if (segment === '**') {
      // Globstar: matches zero or more segments
      if (i === 0) {
        // Leading globstar
        regexPattern += '(?:.*/)?';
      } else if (i === processedSegments.length - 1) {
        // Trailing globstar
        regexPattern += '(?:/.*)?';
      } else {
        // Middle globstar
        regexPattern += '(?:/.*)?/';
      }
    } else if (segment === '') {
      // Empty segment (from // or leading/trailing /)
      regexPattern += '/';
    } else {
      // Normal segment
      regexPattern += segment;
      if (i < processedSegments.length - 1) {
        regexPattern += '/';
      }
    }
  }

  regexPattern += '$';

  const flags = nocase ? 'i' : '';
  try {
    return new RegExp(regexPattern, flags);
  } catch (error) {
    throw new Error(`Invalid regular expression: ${regexPattern}`);
  }
}

/**
 * Translate a glob segment to regex
 * @param {string} segment
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {string}
 */
function translateSegment(segment, options) {
  const { dot, nocase } = options;
  let regex = '';
  let i = 0;

  while (i < segment.length) {
    const char = segment[i];

    if (char === '\\') {
      // Escape character
      i++;
      if (i < segment.length) {
        const nextChar = segment[i];
        // Escape the next character literally
        regex += escapeRegExp(nextChar);
        i++;
      } else {
        // Trailing backslash - error
        throw new GlobError('trailing backslash', i - 1);
      }
    } else if (char === '*') {
      // Wildcard
      regex += '[^/]*';
      i++;
    } else if (char === '?') {
      // Single character wildcard
      regex += '[^/]';
      i++;
    } else if (char === '[') {
      // Character class
      const { classRegex, newIndex } = parseCharacterClass(segment, i, { dot });
      regex += classRegex;
      i = newIndex;
    } else {
      // Regular character
      regex += escapeRegExp(char);
      i++;
    }
  }

  return regex;
