  let negated = false;
  if (i < segment.length && (segment[i] === '!' || segment[i] === '^')) {
    negated = true;
    i++;
  }

  // Handle special case: ] at beginning
  if (i < segment.length && segment[i] === ']') {
    classContent += ']';
    i++;
  }

