      if (classContent.length === 0 || classContent[classContent.length - 1] !== prevChar) {
        classContent += escapeRegExp(prevChar);
      }

      // Add range
      classContent += `-${escapeRegExp(nextChar)}`;

      // Skip the next character as it's part of the range
      i += 2;
    } else {
