/**
 * Match segments recursively
 * @param {string[]} patternSegments
 * @param {string[]} pathSegments
 * @param {number} patternIndex
 * @param {number} pathIndex
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {boolean}
 */
function matchSegments(patternSegments, pathSegments, patternIndex, pathIndex, options) {
  // If we've processed all pattern segments
  if (patternIndex === patternSegments.length) {
    // Success if we've also processed all path segments
    return pathIndex === pathSegments.length;
  }

  // If we've processed all path segments but still have pattern segments
  if (pathIndex === pathSegments.length) {
    // Remaining pattern segments must all be ** to match zero segments
    for (let i = patternIndex; i < patternSegments.length; i++) {
      if (patternSegments[i] !== '**') {
        return false;
      }
    }
    return true;
  }

  const patternSeg = patternSegments[patternIndex];
  const pathSeg = pathSegments[pathIndex];

  if (patternSeg === '**') {
    // Globstar: try matching zero or more segments
    // Try matching zero segments first (skip the **)
    if (matchSegments(patternSegments, pathSegments, patternIndex + 1, pathIndex, options)) {
      return true;
    }
    // Try matching one or more segments (consume a path segment, keep the **)
    return matchSegments(patternSegments, pathSegments, patternIndex, pathIndex + 1, options);
  } else {
    // Normal segment matching
    if (!matchSegment(patternSeg, pathSeg, options)) {
