    return true;
  }

  if (patternSeg.startsWith('\\.')) {
    return true;
  }

  // Check for character classes that definitely allow dot
  if (patternSeg.startsWith('[')) {
    // Parse the character class to see if it allows dot
    try {
      const { allowsDot } = parseCharacterClassForDotCheck(patternSeg, 0);
      return allowsDot;
    } catch (e) {
      // If we can't parse it, assume it doesn't allow dot to be safe
      return false;
    }
  }

  // * and ? alone don't match leading dot
  if (patternSeg === '*' || patternSeg === '?') {
    return false;
  }

  // For other patterns, check if they start with something that could match dot
  // This is a simplified check - in reality we'd need to parse the full segment
  return patternSeg.length > 0 && (patternSeg[0] === '.' || patternSeg.startsWith('\\.'));
}

/**
 * Parse character class to check if it allows dot
 * @param {string} patternSeg
 * @param {number} startIndex
 * @returns {{ allowsDot: boolean }}
 * @throws {GlobError} for malformed character classes
 */
function parseCharacterClassForDotCheck(patternSeg, startIndex) {
  let i = startIndex + 1; // Skip '['

  // Check for negation
  let negated = false;
  if (i < patternSeg.length && (patternSeg[i] === '!' || patternSeg[i] === '^')) {
    negated = true;
    i++;
  }

  // Handle special case: ] at beginning (after optional !/^)
  if (i < patternSeg.length && patternSeg[i] === ']') {
    // Empty class [] or [!] - doesn't allow dot unless negated
    return { allowsDot: !negated };
  }

  // Parse content looking for dot or range that includes dot
  let allowsDot = false;

  while (i < patternSeg.length) {
    const char = patternSeg[i];

    if (char === ']') {
      // End of class
      break;
    } else if (char === '/') {
      throw new GlobError('path separator in character class', startIndex);
    } else if (char === '\\') {
      // Escape
      i++;
      if (i < patternSeg.length) {
        const escapedChar = patternSeg[i];
        if (escapedChar === '.' || (escapedChar === '-' && i + 1 < patternSeg.length && patternSeg[i + 1] === '.')) {
          allowsDot = true;
        }
        i++;
      } else {
        throw new GlobError('trailing backslash', i - 1);
      }
    } else if (char === '.' && !(i > 0 && patternSeg[i - 1] === '[' && 
                                 i + 1 < patternSeg.length && 
                                 patternSeg[i + 1] === '-' && // [.-...] 
                                 !(i + 2 < patternSeg.length && patternSeg[i + 2] === ']'))) { // Not [.-]
      // Dot not part of a range like [.-]
      allowsDot = true;
      i++;
    } else if (char === '-' && 
               i > startIndex + 1 + (negated ? 1 : 0) && // Not at start
               i + 1 < patternSeg.length && 
               patternSeg[i + 1] !== ']') { // Not at end
      // Range
      const startChar = patternSeg[i - 1];
      const endChar = patternSeg[i + 1];
      if ((startChar <= '.' && '.' <= endChar) || 
          (startChar === '.' && endChar >= '.') ||
          (endChar === '.' && startChar <= '.')) {
        allowsDot = true;
      }
      i += 2; // Skip '-' and next char
    } else {
      i++;
    }
  }

