  if (negated) {
    allowsDot = !allowsDot;
  }

  return { allowsDot };
}

/**
 * Convert pattern segment to regex string
 * @param {string} patternSeg
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {string}
 */
function segmentToRegex(patternSeg, options) {
  const { dot, nocase } = options;
  let regex = '';
  let i = 0;

  while (i < patternSeg.length) {
    const char = patternSeg[i];

    if (char === '\\') {
      // Escape character
      i++;
      if (i < patternSeg.length) {
        regex += escapeRegExp(patternSeg[i]);
        i++;
      } else {
        throw new GlobError('trailing backslash', i - 1);
      }
    } else if (char === '*') {
      // Wildcard
      regex += '[^/]*';
      i++;
    } else if (char === '?') {
      // Single character wildcard
      regex += '[^/]';
      i++;
    } else if (char === '[') {
      // Character class
      const { classRegex, newIndex } = parseCharacterClass(patternSeg, i);
      regex += classRegex;
      i = newIndex;
    } else {
      // Regular character
      regex += escapeRegExp(char);
      i++;
    }
  }

  return regex;
}

/**
 * Parse character class [...]
 * @param {string} patternSeg
 * @param {number} startIndex
 * @returns {{ classRegex: string, newIndex: number }}
 * @throws {GlobError} for malformed character classes
 */
function parseCharacterClass(patternSeg, startIndex) {
  let i = startIndex + 1; // Skip '['
  let classContent = '';

  // Check for negation
  let negated = false;
  if (i < patternSeg.length && (patternSeg[i] === '!' || patternSeg[i] === '^')) {
    negated = true;
    i++;
  }

  // Handle special case: ] at beginning (after optional !/^)
  if (i < patternSeg.length && patternSeg[i] === ']') {
    classContent += ']';
    i++;
  }

  // Parse content
  while (i < patternSeg.length) {
    const char = patternSeg[i];

    if (char === ']') {
      // End of class
      i++;
      break;
    } else if (char === '/') {
      throw new GlobError('path separator in character class', startIndex);
    } else if (char === '\\') {
      // Escape
      i++;
      if (i < patternSeg.length) {
        classContent += escapeRegExp(patternSeg[i]);
        i++;
      } else {
        throw new GlobError('trailing backslash', i - 1);
      }
    } else if (char === '-' && 
               i > startIndex + 1 + (negated ? 1 : 0) && // Not at start
               i + 1 < patternSeg.length && 
               patternSeg[i + 1] !== ']') { // Not at end
      // Range
      const startChar = patternSeg[i - 1];
      const endChar = patternSeg[i + 1];
      classContent += escapeRegExp(startChar) + '-' + escapeRegExp(endChar);
      i += 2; // Skip '-' and next char
    } else {
      // Regular character
      classContent += escapeRegExp(char);
      i++;
    }
  }

  // Check if we found closing ]
  if (i <= startIndex + 1 || patternSeg[i - 1] !== ']') {
    throw new GlobError('unterminated character class', startIndex);
  }

  // Build character class
  let charClass = `[${classContent}]`;
  if (negated) {
    charClass = `[^${classContent}]`;
  }

  return { classRegex: charClass, newIndex: i };
}

/**
 * Escape regex special characters
 * @param {string} char
 * @returns {string}
 */
function escapeRegExp(char) {
  return char.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}"}

