{"file_path":"src/glob.js","content":"/**
 * Glob patterns compiled to path matchers: wildcards that stop at `/`,
 * whole-segment globstars, POSIX-style character classes, backslash escapes and
 * the leading-dot rule.
 */

/** Failure raised while compiling a pattern. */
export class GlobError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [index] 0-based index into the pattern where the fault starts
   */
  constructor(message, index) {
    super(message);
    this.name = 'GlobError';
    this.index = index;
  }
}

/**
 * Compile a glob pattern into a matcher.
 *
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {(path: string) => boolean} matcher for whole paths
 */
export function compile(pattern, options = {}) {
  if (typeof pattern !== 'string') {
    throw new Error('pattern must be a string');
  }
  if (pattern === '') {
    throw new Error('pattern must not be empty');
  }

  const { dot = false, nocase = false } = options;
  const matcher = compileToMatcher(pattern, { dot, nocase });
  return matcher;
}

/**
 * Test one path against one pattern.
 *
 * @param {string} path path to test
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {boolean} whether the whole path matches
 */
export function isMatch(path, pattern, options = {}) {
  if (typeof path !== 'string') {
    throw new Error('path must be a string');
  }
  return compile(pattern, options)(path);
}

/**
 * Keep the paths that match a pattern, in their original order.
 *
 * @param {string[]} paths paths to filter
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {string[]} the matching paths
 */
export function filter(paths, pattern, options = {}) {
  if (!Array.isArray(paths)) {
    throw new Error('paths must be an array');
  }
  const matcher = compile(pattern, options);
  return paths.filter(matcher);
}

/**
 * Compile pattern to matcher function
 * @param {string} pattern
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {(path: string) => boolean}
 */
function compileToMatcher(pattern, options) {
  const { dot, nocase } = options;

  // Parse pattern into segments
  const segments = [];
  let current = '';
  let i = 0;

  while (i <= pattern.length) {
    if (i === pattern.length || pattern[i] === '/') {
      segments.push(current);
      current = '';
      i++; // Move past the slash or to the end
    } else {
      current += pattern[i];
      i++;
    }
  }

  // Remove trailing empty segment if pattern doesn't end with /
  if (segments.length > 0 && segments[segments.length - 1] === '' && !pattern.endsWith('/')) {
    segments.pop();
  }

  // Process segments to handle **
  const processedSegments = [];
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i];
    if (seg === '**') {
      // Only add ** if not already the last added segment (collapse adjacent)
      if (processedSegments.length === 0 || processedSegments[processedSegments.length - 1] !== '**') {
        processedSegments.push('**');
      }
    } else {
      processedSegments.push(seg);
    }
  }

  // Return matcher function
  return (path) => {
    const pathSegments = path.split('/');
    return matchSegments(processedSegments, pathSegments, 0, 0, { dot, nocase });
  };
}

/**
 * Match segments recursively
 * @param {string[]} patternSegments
 * @param {string[]} pathSegments
 * @param {number} patternIndex
 * @param {number} pathIndex
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {boolean}
 */
function matchSegments(patternSegments, pathSegments, patternIndex, pathIndex, options) {
  // If we've processed all pattern segments
  if (patternIndex === patternSegments.length) {
    // Success if we've also processed all path segments
    return pathIndex === pathSegments.length;
  }

  // If we've processed all path segments but still have pattern segments
  if (pathIndex === pathSegments.length) {
    // Remaining pattern segments must all be ** to match zero segments
    for (let i = patternIndex; i < patternSegments.length; i++) {
      if (patternSegments[i] !== '**') {
        return false;
      }
    }
    return true;
  }

  const patternSeg = patternSegments[patternIndex];
  const pathSeg = pathSegments[pathIndex];

  if (patternSeg === '**') {
    // Globstar: try matching zero or more segments
    // Try matching zero segments first (skip the **)
    if (matchSegments(patternSegments, pathSegments, patternIndex + 1, pathIndex, options)) {
      return true;
    }
    // Try matching one or more segments (consume a path segment, keep the **)
    // But only if consuming this segment is allowed (respect dot rule for **)
    if (!pathSeg.startsWith('.') || options.dot) {
      return matchSegments(patternSegments, pathSegments, patternIndex, pathIndex + 1, options);
    }
    return false;
  } else {
    // Normal segment matching
    if (!matchSegment(patternSeg, pathSeg, options)) {
      return false;
    }
    return matchSegments(patternSegments, pathSegments, patternIndex + 1, pathIndex + 1, options);
  }
}

/**
 * Match a single pattern segment against a path segment
 * @param {string} patternSeg
 * @param {string} pathSeg
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {boolean}
 */
function matchSegment(patternSeg, pathSeg, options) {
  const { dot, nocase } = options;

  // Handle leading dot rule
  if (!dot && pathSeg.startsWith('.')) {
    // Check if pattern could match a leading dot
    if (!couldMatchLeadingDot(patternSeg)) {
      return false;
    }
  }

  // Convert pattern segment to regex and test
  const regexStr = segmentToRegex(patternSeg, { dot, nocase });
  try {
    const regex = new RegExp(`^${regexStr}$`, nocase ? 'i' : '');
    return regex.test(pathSeg);
  } catch (e) {
    return false;
  }
}

/**
 * Check if a pattern segment could possibly match a leading dot
 * @param {string} patternSeg
 * @returns {boolean}
 */
function couldMatchLeadingDot(patternSeg) {
  // Patterns that could match a leading dot:
  // - .* (explicit dot) - but * alone doesn't match leading dot
  // - \. (escaped dot)
  // - Character classes that include dot 
  // But NOT:
  // - * (wildcard) alone
  // - ? (single char wildcard) alone
  // - Character classes that don't explicitly allow dot

  if (patternSeg === '.' || patternSeg === '\\.') {
    return true;
  }

  if (patternSeg.startsWith('\\.')) {
    return true;
  }

  // Check for character classes that definitely allow dot
  if (patternSeg.startsWith('[')) {
    // Parse the character class to see if it allows dot
    try {
      const { allowsDot } = parseCharacterClassForDotCheck(patternSeg, 0);
      return allowsDot;
    } catch (e) {
      // If we can't parse it, assume it doesn't allow dot to be safe
      return false;
    }
  }

  // * and ? alone don't match leading dot
  if (patternSeg === '*' || patternSeg === '?') {
    return false;
  }

  // For other patterns, check if they start with something that could match dot
  // This is a simplified check - in reality we'd need to parse the full segment
  return patternSeg.length > 0 && (patternSeg[0] === '.' || patternSeg.startsWith('\\.'));
}

/**
 * Parse character class to check if it allows dot
 * @param {string} patternSeg
 * @param {number} startIndex
 * @returns {{ allowsDot: boolean }}
 * @throws {GlobError} for malformed character classes
 */
function parseCharacterClassForDotCheck(patternSeg, startIndex) {
  let i = startIndex + 1; // Skip '['

  // Check for negation
  let negated = false;
  if (i < patternSeg.length && (patternSeg[i] === '!' || patternSeg[i] === '^')) {
    negated = true;
    i++;
  }

  // Handle special case: ] at beginning (after optional !/^)
  if (i < patternSeg.length && patternSeg[i] === ']') {
    // Empty class [] or [!] - doesn't allow dot unless negated
    return { allowsDot: !negated };
  }

  // Parse content looking for dot or range that includes dot
  let allowsDot = false;

  while (i < patternSeg.length) {
    const char = patternSeg[i];

    if (char === ']') {
      // End of class
      break;
    } else if (char === '/') {
      throw new GlobError('path separator in character class', startIndex);
    } else if (char === '\\') {
      // Escape
      i++;
      if (i < patternSeg.length) {
        const escapedChar = patternSeg[i];
        if (escapedChar === '.' || (escapedChar === '-' && i + 1 < patternSeg.length && patternSeg[i + 1] === '.')) {
          allowsDot = true;
        }
        i++;
      } else {
        throw new GlobError('trailing backslash', i - 1);
      }
    } else if (char === '.' && !(i > 0 && patternSeg[i - 1] === '[' && 
                                 i + 1 < patternSeg.length && 
                                 patternSeg[i + 1] === '-' && // [.-...] 
                                 !(i + 2 < patternSeg.length && patternSeg[i + 2] === ']'))) { // Not [.-]
      // Dot not part of a range like [.-]
      allowsDot = true;
      i++;
    } else if (char === '-' && 
               i > startIndex + 1 + (negated ? 1 : 0) && // Not at start
               i + 1 < patternSeg.length && 
               patternSeg[i + 1] !== ']') { // Not at end
      // Range
      const startChar = patternSeg[i - 1];
      const endChar = patternSeg[i + 1];
      if ((startChar <= '.' && '.' <= endChar) || 
          (startChar === '.' && endChar >= '.') ||
          (endChar === '.' && startChar <= '.')) {
        allowsDot = true;
      }
      i += 2; // Skip '-' and next char
    } else {
      i++;
    }
  }

  // Check if we found closing ]
  if (i >= patternSeg.length || patternSeg[i] !== ']') {
    throw new GlobError('unterminated character class', startIndex);
  }

  // Apply negation
  if (negated) {
    allowsDot = !allowsDot;
  }

  return { allowsDot };
}

/**
 * Convert pattern segment to regex string
 * @param {string} patternSeg
 * @param {{ dot: boolean, nocase: boolean }} options
 * @returns {string}
 */
function segmentToRegex(patternSeg, options) {
  const { dot, nocase } = options;
  let regex = '';
  let i = 0;

  while (i < patternSeg.length) {
    const char = patternSeg[i];

    if (char === '\\') {
      // Escape character
      i++;
      if (i < patternSeg.length) {
        regex += escapeRegExp(patternSeg[i]);
        i++;
      } else {
        throw new GlobError('trailing backslash', i - 1);
      }
    } else if (char === '*') {
      // Wildcard
      regex += '[^/]*';
      i++;
    } else if (char === '?') {
      // Single character wildcard
      regex += '[^/]';
      i++;
    } else if (char === '[') {
      // Character class
      const { classRegex, newIndex } = parseCharacterClass(patternSeg, i);
      regex += classRegex;
      i = newIndex;
    } else {
      // Regular character
      regex += escapeRegExp(char);
      i++;
    }
  }

  return regex;
}

/**
 * Parse character class [...]
 * @param {string} patternSeg
 * @param {number} startIndex
 * @returns {{ classRegex: string, newIndex: number }}
 * @throws {GlobError} for malformed character classes
 */
function parseCharacterClass(patternSeg, startIndex) {
  let i = startIndex + 1; // Skip '[']
  let classContent = '';

  // Check for negation
  let negated = false;
  if (i < patternSeg.length && (patternSeg[i] === '!' || patternSeg[i] === '^')) {
    negated = true;
    i++;
  }

  // Handle special case: ] at beginning (after optional !/^)
  if (i < patternSeg.length && patternSeg[i] === ']') {
    classContent += ']';
    i++;
  }

  // Parse content
  while (i < patternSeg.length) {
    const char = patternSeg[i];

    if (char === ']') {
      // End of class
      i++;
      break;
    } else if (char === '/') {
      throw new GlobError('path separator in character class', startIndex);
    } else if (char === '\\') {
      // Escape
      i++;
      if (i < patternSeg.length) {
        classContent += escapeRegExp(patternSeg[i]);
        i++;
      } else {
        throw new GlobError('trailing backslash', i - 1);
      }
    } else if (char === '-' && 
               i > startIndex + 1 + (negated ? 1 : 0) && // Not at start
               i + 1 < patternSeg.length && 
               patternSeg[i + 1] !== ']') { // Not at end
      // Range
      const startChar = patternSeg[i - 1];
      const endChar = patternSeg[i + 1];
      classContent += escapeRegExp(startChar) + '-' + escapeRegExp(endChar);
      i += 2; // Skip '-' and next char
    } else {
      // Regular character
      classContent += escapeRegExp(char);
      i++;
    }
  }

  // Check if we found closing ]
  if (i <= startIndex + 1 || patternSeg[i - 1] !== ']') {
    throw new GlobError('unterminated character class', startIndex);
  }

  // Build character class
  let charClass = `[${classContent}]`;
  if (negated) {
    charClass = `[^${classContent}]`;
  }

  return { classRegex: charClass, newIndex: i };
}

/**
 * Escape regex special characters
 * @param {string} char
 * @returns {string}
 */
function escapeRegExp(char) {
  return char.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}"}

